
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_lambda_oc2_n_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_lambda_oc2_n", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.301324731326412e+00, -4.219492971913853e+00, -4.104922423165273e+00, -3.946412481481218e+00, -3.730835232713182e+00, -3.444767870841202e+00, -3.078273443795124e+00, -2.631479022453600e+00, -2.122306963846799e+00, -1.586261366455793e+00, -1.063025259820604e+00, -7.068941904516025e-01, -6.019845354713257e-01, -5.003957372637826e-01, -3.670965003873439e-01, -2.349909099629597e-01, -1.226628021603747e-01, -4.388352077457980e-02, -9.517086134338788e-03, -1.070182511773154e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


